def _pp_born_01_LL(v, Nc):
    '''Class 1, q qp -> q, helicity difference (LL): Born term with s = 1, alphaS = 1.'''
    born = -(-1 + Nc)*(1 + Nc)*(1 + v)/(2*Nc**2*(-1 + v)*v)
    return born


