def _pp_born_03_UU(v, Nc):
    '''Class 3, q qpb -> q, spin average (UU): Born term with s = 1, alphaS = 1.'''
    born = (-1 + Nc)*(1 + Nc)*(1 + v**2)/(2*Nc**2*(-1 + v)**2*v)
    return born


