    '''Class 5, q qb -> qp, helicity difference (LL): Born term with s = 1, alphaS = 1.'''
    born = -(-1 + Nc)*(1 + Nc)*(1 - 2*v + 2*v**2)/(2*Nc**2*v)
    return born


