def _pp_born_11_UU(v, Nc):
    '''Class 11, q qb -> q, spin average (UU): Born term with s = 1, alphaS = 1.'''
    born = (
        (-1 + Nc)*(1 + Nc)*(Nc - 2*Nc*v + v**2 + 4*Nc*v**2 - v**3 - 3*Nc*v**3 + Nc*v**4)/(Nc**3*(-1
        + v)**2*v)
    )
    return born


