def _pp_born_12_LL(v, Nc):
    '''Class 12, q qb -> g, helicity difference (LL): Born term with s = 1, alphaS = 1.'''
    born = (
        (-1 + Nc)*(1 + Nc)*(1 - 2*v + 2*v**2)*(-1 + Nc**2 - 2*Nc**2*v + 2*Nc**2*v**2)/(2*Nc**3*(-1
        + v)*v**2)
    )
    return born


