def _pp_born_14_UU(v, Nc):
    '''Class 14, q g -> g, spin average (UU): Born term with s = 1, alphaS = 1.'''
    born = (
        -(2 - 2*v + v**2)*(2*Nc**2 - 2*Nc**2*v - v**2 + Nc**2*v**2)/(2*Nc**2*(-1 + v)*v**3)
    )
    return born


