def _pp_born_14_LL(v, Nc):
    '''Class 14, q g -> g, helicity difference (LL): Born term with s = 1, alphaS = 1.'''
    born = (-2 + v)*(2*Nc**2 - 2*Nc**2*v - v**2 + Nc**2*v**2)/(2*Nc**2*(-1 + v)*v**2)
    return born


