def _pp_born_15_LL(v, Nc):
    '''Class 15, g g -> g, helicity difference (LL): Born term with s = 1, alphaS = 1.'''
    born = -4*Nc**2*(1 - v + v**2)*(2 - v + v**2)/((-1 + Nc)*(1 + Nc)*(-1 + v)*v**2)
    return born


