def _pp_born_16_UU(v, Nc):
    '''Class 16, g g -> q, spin average (UU): Born term with s = 1, alphaS = 1.'''
    born = (
        -(1 - 2*v + 2*v**2)*(-1 + Nc**2 - 2*Nc**2*v + 2*Nc**2*v**2)/(2*(-1 + Nc)*Nc*(1 + Nc)*(-1
        + v)*v**2)
    )
    return born


