def _pp_born_16_LL(v, Nc):
    '''Class 16, g g -> q, helicity difference (LL): Born term with s = 1, alphaS = 1.'''
    born = (
        (1 - 2*v + 2*v**2)*(-1 + Nc**2 - 2*Nc**2*v + 2*Nc**2*v**2)/(2*(-1 + Nc)*Nc*(1 + Nc)*(-1
        + v)*v**2)
    )
    return born


def _pp_prefactor(v, w):
    '''Proton-proton prefactor alphaS^3/(pi s v w) at s = 1, alphaS = 1.'''
    prefactor = 1/(pi*v*w)
    return prefactor


