def _tt_born_11(v, Nc):
    '''TT class 11, q qb -> q: Born term with s = 1, alphaS = 1.'''
    born = -(-1 + Nc)*(1 + Nc)*(-1 - Nc + Nc*v)/Nc**3
    return born


