        - 2*Nc**2*v**2*w - v**3*w + Nc**2*v**3*w + 3*v**2*w**2 - 3*Nc**2*v**2*w**2 - 2*v**3*w**2
        + 2*Nc**2*v**3*w**2 + v**4*w**2 - Nc**2*v**4*w**2 + v**3*w**3 + 3*Nc**2*v**3*w**3 - 5*v**4*w**3
